CREATE TABLE IF NOT EXISTS "CLASES_PLANIFICACION" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UNIDAD_ID" BIGINT NOT NULL,
    "TITULO" VARCHAR(180) NOT NULL,
    "FECHA_PLANIFICADA" DATE NOT NULL,
    "DURACION_CODIGO" VARCHAR(30) NOT NULL,
    "DURACION_LABEL" VARCHAR(80) NOT NULL,
    "OA_CODIGO" VARCHAR(60),
    "OA_TITULO" VARCHAR(180) NOT NULL,
    "OA_DESCRIPCION" TEXT,
    "TIPO_EVALUACION" VARCHAR(30) NOT NULL,
    "INICIO_ACTIVIDAD" TEXT,
    "DESARROLLO_ACTIVIDAD" TEXT,
    "CIERRE_ACTIVIDAD" TEXT,
    "ESTADO" VARCHAR(20) NOT NULL,
    "PUBLICADO_A_ALUMNOS" BOOLEAN NOT NULL DEFAULT FALSE,
    "CREADO_POR_USUARIO_ID" BIGINT NOT NULL,
    "FECHA_CREACION" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "FECHA_ACTUALIZACION" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_CLASES_PLANIFICACION_UNIDAD"
        FOREIGN KEY ("UNIDAD_ID") REFERENCES "UNIDADES_PLANIFICACION" ("ID"),
    CONSTRAINT "FK_CLASES_PLANIFICACION_USUARIO"
        FOREIGN KEY ("CREADO_POR_USUARIO_ID") REFERENCES "USUARIOS" ("ID"),
    CONSTRAINT "CHK_CLASES_PLANIFICACION_ESTADO"
        CHECK ("ESTADO" IN ('BORRADOR', 'PUBLICADA')),
    CONSTRAINT "CHK_CLASES_PLANIFICACION_TIPO_EVALUACION"
        CHECK ("TIPO_EVALUACION" IN ('FORMATIVA', 'SUMATIVA', 'DIAGNOSTICA', 'SIN_EVALUACION'))
);

CREATE TABLE IF NOT EXISTS "CLASES_PLANIFICACION_DOCUMENTOS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CLASE_ID" BIGINT NOT NULL,
    "NOMBRE_ORIGINAL" VARCHAR(255) NOT NULL,
    "NOMBRE_ARCHIVO" VARCHAR(255) NOT NULL,
    "EXTENSION" VARCHAR(15) NOT NULL,
    "MIME_TYPE" VARCHAR(120) NOT NULL,
    "PESO_BYTES" BIGINT NOT NULL,
    "RUTA_ARCHIVO" VARCHAR(500) NOT NULL,
    "VISIBLE_ALUMNOS" BOOLEAN NOT NULL DEFAULT FALSE,
    "FECHA_CARGA" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_CLASES_PLANIFICACION_DOCUMENTOS_CLASE"
        FOREIGN KEY ("CLASE_ID") REFERENCES "CLASES_PLANIFICACION" ("ID") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IDX_CLASES_PLANIFICACION_UNIDAD"
    ON "CLASES_PLANIFICACION" ("UNIDAD_ID");

CREATE INDEX IF NOT EXISTS "IDX_CLASES_PLANIFICACION_ESTADO"
    ON "CLASES_PLANIFICACION" ("ESTADO");

CREATE INDEX IF NOT EXISTS "IDX_CLASES_PLANIFICACION_FECHA"
    ON "CLASES_PLANIFICACION" ("FECHA_PLANIFICADA");

CREATE INDEX IF NOT EXISTS "IDX_CLASES_PLANIFICACION_DOCUMENTOS_CLASE"
    ON "CLASES_PLANIFICACION_DOCUMENTOS" ("CLASE_ID");

INSERT INTO "CLASES_PLANIFICACION" (
    "UNIDAD_ID",
    "TITULO",
    "FECHA_PLANIFICADA",
    "DURACION_CODIGO",
    "DURACION_LABEL",
    "OA_CODIGO",
    "OA_TITULO",
    "OA_DESCRIPCION",
    "TIPO_EVALUACION",
    "INICIO_ACTIVIDAD",
    "DESARROLLO_ACTIVIDAD",
    "CIERRE_ACTIVIDAD",
    "ESTADO",
    "PUBLICADO_A_ALUMNOS",
    "CREADO_POR_USUARIO_ID"
)
SELECT
    up."ID",
    'Precipitacion y sus tipos en Chile Central',
    DATE '2026-04-14',
    'CUATRO_SEMANAS',
    '4 semanas',
    'UP-' || up."ID" || '-OA-1',
    'OA principal de la unidad',
    up."OBJETIVOS_APRENDIZAJE",
    'FORMATIVA',
    'Pregunta detonante sobre lluvia y observacion de experiencias cotidianas.',
    'Video guiado, mapa de precipitaciones y analisis grupal de San Bernardo.',
    'Ticket de salida con dibujo del ciclo del agua y precipitacion.',
    'PUBLICADA',
    TRUE,
    up."CREADO_POR_USUARIO_ID"
FROM "UNIDADES_PLANIFICACION" up
WHERE NOT EXISTS (
    SELECT 1
    FROM "CLASES_PLANIFICACION" cp
    WHERE cp."UNIDAD_ID" = up."ID"
      AND cp."TITULO" = 'Precipitacion y sus tipos en Chile Central'
)
LIMIT 1;
